def min_max_gas_dist(stations, k):
    gaps = [stations[i + 1] - stations[i] for i in range(len(stations) - 1)]

    def stations_needed(d):
        return sum(int(gap / d) for gap in gaps)

    lo, hi = 0.0, max(gaps)

    for _ in range(100):
        mid = (lo + hi) / 2
        if stations_needed(mid) > k:
            lo = mid
        else:
            hi = mid

    return round(hi, 6)

